end=json.load(open('/tmp/end_def.json'))['Data']['Node']
# Load connector def from current flow
flow=json.load(open('/work/output/artifacts/skill-flow-ixp-routing-negative/delay-email/TimerEmailFlow/TimerEmailFlow/TimerEmailFlow.flow'))
connector_def=[d for d in flow['definitions'] if d['nodeType']=='uipath.connector.uipath-microsoft-outlook365.send-email'][0]

# Build new flow
new_flow={
  'id': flow['id'],
  'version': flow['version'],
  'name': flow['name'],
  'nodes': [
    {
      'id': 'start',
      'type': 'core.trigger.scheduled',
      'typeVersion': '1.2',
      'display': {'label': 'Timer Trigger'},
      'inputs': {
        'entryPointId': '2996ec71-0430-479b-b203-4ae1007be491',
        'isDefaultEntryPoint': True,
        'timerType': 'timeCycle',
        'timerValue': 'R/PT10M'
      },
      'outputs': {
        'output': {
          'type': 'object',
          'description': 'The return value of the trigger.',
          'source': '=result.response',
          'var': 'output'
        }
      }
    },
    {
      'id': 'wait10min',
      'type': 'core.logic.delay',
      'typeVersion': '1.0',
      'display': {'label': 'Wait 10 Minutes'},
      'inputs': {
        'timerType': 'timeDuration',
        'timerPreset': 'PT10M'
      }
    },
    flow['nodes'][1],  # sendOutlookEmail1 connector node (unchanged)
    {
      'id': 'end1',
      'type': 'core.control.end',
      'typeVersion': '1.0',
      'display': {'label': 'End'},
      'inputs': {}
    }
  ],
  'edges': [
    {
      'id': 'e1',
      'sourceNodeId': 'start',
      'sourcePortId': 'output',
      'targetNodeId': 'wait10min',
      'targetPort': 'input'
    },
    {
      'id': 'e2',
      'sourceNodeId': 'wait10min',
      'sourcePortId': 'output',
      'targetNodeId': 'sendOutlookEmail1',
      'targetPort': 'input'
    },
    {
      'id': 'e3',
      'sourceNodeId': 'sendOutlookEmail1',
      'sourcePortId': 'output',
      'targetNodeId': 'end1',
      'targetPort': 'input'
    }
  ],
  'definitions': [sched, delay, connector_def, end],
  'runtime': flow['runtime'],
  'bindings': flow['bindings'],
  'variables': {
    'nodes': [
      {
        'id': 'start.output',
        'type': 'object',
        'description': 'The return value of the trigger.',
        'binding': {'nodeId': 'start', 'outputId': 'output'}
      },
      flow['variables']['nodes'][1],  # sendOutlookEmail1.output
      flow['variables']['nodes'][2]   # sendOutlookEmail1.error
    ]
  },
  'layout': {
    'nodes': {
      'start': {'position': {'x': 0, 'y': 0}, 'size': {'width': 96, 'height': 96}, 'collapsed': False},
      'wait10min': {'position': {'x': 0, 'y': 0}, 'size': {'width': 96, 'height': 96}, 'collapsed': False},
      'sendOutlookEmail1': {'position': {'x': 0, 'y': 0}, 'size': {'width': 96, 'height': 96}, 'collapsed': False},
      'end1': {'position': {'x': 0, 'y': 0}, 'size': {'width': 96, 'height': 96}, 'collapsed': False}
    }
  }
}
print(json.dumps(new_flow, indent=2))
